class Solution {
public:
    bool areSentencesSimilar(vector<string>& sentence1, vector<string>& sentence2, vector<vector<string>>& similarPairs) {
        if (sentence1.size() != sentence2.size()) return false;
        set<pair<string, string>> simSet;
        for (const auto& pair : similarPairs) {
            simSet.insert({pair[0], pair[1]});
            simSet.insert({pair[1], pair[0]});
        }
        for (size_t i = 0; i < sentence1.size(); ++i) {
            if (sentence1[i] != sentence2[i] && !simSet.count({sentence1[i], sentence2[i]})) {
                return false;
            }
        }
        return true;
    }
};

class Solution {
    public boolean areSentencesSimilar(String[] sentence1, String[] sentence2, List<List<String>> similarPairs) {
        if (sentence1.length != sentence2.length) return false;
        Set<String> simSet = new HashSet<>();
        for (List<String> pair : similarPairs) {
            simSet.add(pair.get(0) + "#" + pair.get(1));
            simSet.add(pair.get(1) + "#" + pair.get(0));
        }
        for (int i = 0; i < sentence1.length; i++) {
            if (!sentence1[i].equals(sentence2[i]) && !simSet.contains(sentence1[i] + "#" + sentence2[i])) {
                return false;
            }
        }
        return true;
    }
}

/**
 * @param {string[]} sentence1
 * @param {string[]} sentence2
 * @param {string[][]} similarPairs
 * @return {boolean}
